{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Scale history embeddings by fixed inverse-frequency weights computed solely from each category's training interactions. This may reduce dominance by frequent history items while preserving learned embeddings, GRU topology, readout, candidate scoring, loss and optimizer. A persistent buffer saves the feature weights in each checkpoint; the generated predictor imports the updated model class and restores them automatically.",
      "edits": [
        {
          "find": "DATA_DIR = os.environ.get(\"GAGC_DATA_DIR\", \"./input/trainval\")",
          "replace": "DATA_DIR = os.environ['GAGC_DATA_DIR']"
        },
        {
          "find": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        dropout = dropout_rate if num_layers > 1 else 0.0",
          "replace": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        self.register_buffer(\"input_frequency_weight\", torch.ones(itemnum + 1))\n        self.input_frequency_weight[0] = 0.0\n        dropout = dropout_rate if num_layers > 1 else 0.0"
        },
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq) * self.input_frequency_weight[seq].unsqueeze(-1))"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq) * self.input_frequency_weight[seq].unsqueeze(-1))"
        },
        {
          "find": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    counts = np.zeros(itemnum + 1, dtype=np.int64)\n    for history in user_train.values():\n        np.add.at(counts, np.asarray(history, dtype=np.int64), 1)\n    positive_counts = counts[1:][counts[1:] > 0]\n    median_frequency = float(np.median(positive_counts)) if positive_counts.size else 1.0\n    frequency_weights = np.clip(\n        np.maximum(counts.astype(np.float64) / median_frequency, 1e-12) ** (-0.15),\n        0.5, 2.0,\n    ).astype(np.float32)\n    frequency_weights[0] = 0.0\n    with torch.no_grad():\n        model.input_frequency_weight.copy_(torch.from_numpy(frequency_weights).to(device))\n\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
        }
      ]
    }
  ],
  "change_summary": "Apply checkpointed training-frequency scaling exclusively to history inputs for all four category models. Predictor loading restores the saved weights through the imported model class. GRU, scoring, optimization, splits and training schedule remain unchanged."
}
